@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class PersonalAccount {}

class BusinessAccount {
  + CompanyName : string
  + MonthlyFee : double
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

class FriendRequest {
  + Status : string
}

User "1" -- "1" Account
Account --|> PersonalAccount
Account --|> BusinessAccount

PersonalAccount "1" -- "0..*" FriendRequest
PersonalAccount "1" -- "0..*" Page : manage
PersonalAccount "1" -- "0..*" Page : privilege

BusinessAccount "1" -- "0..*" Page
BusinessAccount "1" -- "0..*" AdvertisementPage

Page --|> AdvertisementPage

@enduml

